from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import ArticleTranslation

class ArticleTranslationUpdateView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def put(self, request, translation_id):
        # Ensure the parent master model belongs to the authenticated user's organization
        try:
            trans = ArticleTranslation.objects.select_related('master').get(
                pk=translation_id,
                master__organization=request.user.organization
            )
        except ArticleTranslation.DoesNotExist:
            return Response({'error': 'Translation record not found'}, status=status.HTTP_404_NOT_FOUND)

        trans.title = request.data.get('title', trans.title)
        trans.content = request.data.get('content', trans.content)
        trans.save(update_fields=['title', 'content'])
        return Response({'status': 'updated', 'language_code': trans.language_code})
